const express = require('express');
const { execFile, spawn } = require('child_process');
const path = require('path');
const crypto = require('crypto');
const fs = require('fs').promises;

const app = express();
const UPLOAD_DIR = '/tmp/img_processing';
const ALLOWED_FORMATS = ['png', 'jpg', 'jpeg', 'webp', 'gif'];

let activeJobs = new Map();
let shuttingDown = false;

// Sanitize filename - remove dangerous characters
function sanitizeFilename(name) {
  return name.replace(/[^a-zA-Z0-9._-]/g, '_');
}

// Validate image format
function validateFormat(format) {
  return ALLOWED_FORMATS.includes(format.toLowerCase());
}

// Generate safe output path
function generateOutputPath(jobId, format) {
  const safeFormat = format.replace(/[^a-z]/g, '');
  return path.join(UPLOAD_DIR, `${jobId}_output.${safeFormat}`);
}

// Image metadata extraction using identify (ImageMagick)
async function extractMetadata(filePath) {
  return new Promise((resolve, reject) => {
    execFile('/usr/bin/identify', ['-verbose', filePath], (err, stdout) => {
      if (err) return reject(err);
      resolve(stdout);
    });
  });
}

// Core conversion engine
class ConversionEngine {
  constructor(options = {}) {
    this.quality = Math.min(100, Math.max(1, parseInt(options.quality) || 85));
    this.maxWidth = Math.min(4096, Math.max(1, parseInt(options.maxWidth) || 1920));
    this.maxHeight = Math.min(4096, Math.max(1, parseInt(options.maxHeight) || 1080));
    this.stripMetadata = options.stripMetadata !== false;
    this.profileName = options.profileName || 'default';
  }

  buildArgs(inputPath, outputPath) {
    const args = [inputPath];
    args.push('-resize', `${this.maxWidth}x${this.maxHeight}>`);
    args.push('-quality', String(this.quality));
    if (this.stripMetadata) {
      args.push('-strip');
    }
    args.push(outputPath);
    return args;
  }

  async convert(inputPath, outputPath) {
    const args = this.buildArgs(inputPath, outputPath);
    return new Promise((resolve, reject) => {
      const proc = execFile('/usr/bin/convert', args, (err, stdout, stderr) => {
        if (err) return reject(err);
        resolve({ stdout, stderr });
      });
      return proc;
    });
  }
}

// Profile registry for conversion presets
class ProfileRegistry {
  constructor() {
    this.profiles = new Map();
    this.profiles.set('default', { quality: 85, maxWidth: 1920, maxHeight: 1080 });
    this.profiles.set('thumbnail', { quality: 70, maxWidth: 256, maxHeight: 256 });
    this.profiles.set('hd', { quality: 90, maxWidth: 3840, maxHeight: 2160 });
  }

  get(name) {
    return this.profiles.get(name) || this.profiles.get('default');
  }

  register(name, config) {
    const safeName = name.replace(/[^a-zA-Z0-9_-]/g, '');
    this.profiles.set(safeName, {
      quality: Math.min(100, Math.max(1, parseInt(config.quality) || 85)),
      maxWidth: Math.min(4096, Math.max(1, parseInt(config.maxWidth) || 1920)),
      maxHeight: Math.min(4096, Math.max(1, parseInt(config.maxHeight) || 1080))
    });
  }
}

const registry = new ProfileRegistry();

// Graceful shutdown handler with job completion tracking
class ShutdownManager {
  constructor() {
    this.drainCallbacks = [];
    this.jobCompletionLog = path.join(UPLOAD_DIR, 'completion.log');
  }

  registerJob(jobId, metadata) {
    activeJobs.set(jobId, { ...metadata, startTime: Date.now() });
  }

  async completeJob(jobId, status) {
    const job = activeJobs.get(jobId);
    if (job) {
      const duration = Date.now() - job.startTime;
      const logEntry = `${jobId}|${job.originalName}|${status}|${duration}ms`;
      await fs.appendFile(this.jobCompletionLog, logEntry + '\n');
      activeJobs.delete(jobId);
    }
    if (shuttingDown && activeJobs.size === 0) {
      this.drainCallbacks.forEach(cb => cb());
    }
  }

  onDrain(cb) {
    this.drainCallbacks.push(cb);
  }
}

const shutdownMgr = new ShutdownManager();

// Watermark application - uses composite command
async function applyWatermark(imagePath, watermarkText, outputPath) {
  // Strict whitelist: only allow alphanumeric, spaces, and basic punctuation
  const safeText = watermarkText.replace(/[^a-zA-Z0-9 .,:!?@#&()-]/g, '');
  if (safeText.length === 0 || safeText.length > 100) {
    throw new Error('Invalid watermark text');
  }

  return new Promise((resolve, reject) => {
    const proc = spawn('/usr/bin/composite', [
      '-gravity', 'SouthEast',
      '-geometry', '+10+10',
      `label:${safeText}`,
      imagePath,
      outputPath
    ], { shell: false });

    proc.on('close', (code) => {
      if (code === 0) resolve();
      else reject(new Error(`composite exited with code ${code}`));
    });
    proc.on('error', reject);
  });
}

// Pipeline orchestrator
async function processImage(jobId, inputPath, options) {
  const engine = new ConversionEngine(options);
  const outputFormat = options.outputFormat || 'png';
  const outputPath = generateOutputPath(jobId, outputFormat);

  // Step 1: Validate input exists
  await fs.access(inputPath);

  // Step 2: Extract and log metadata
  const metadata = await extractMetadata(inputPath);

  // Step 3: Convert
  await engine.convert(inputPath, outputPath);

  // Step 4: Apply watermark if requested
  if (options.watermark) {
    const watermarkedPath = outputPath.replace(/\.([^.]+)$/, '_wm.$1');
    await applyWatermark(outputPath, options.watermark, watermarkedPath);
    return watermarkedPath;
  }

  return outputPath;
}

// POST /convert - main endpoint
app.post('/convert', express.json(), async (req, res) => {
  if (shuttingDown) {
    return res.status(503).json({ error: 'Server shutting down' });
  }

  const { filename, format, profile, watermark, quality, maxWidth, maxHeight } = req.body;

  if (!filename || !format) {
    return res.status(400).json({ error: 'filename and format required' });
  }

  if (!validateFormat(format)) {
    return res.status(400).json({ error: 'Invalid output format' });
  }

  const sanitized = sanitizeFilename(filename);
  const inputPath = path.join(UPLOAD_DIR, sanitized);

  // Ensure path doesn't escape upload dir
  if (!inputPath.startsWith(UPLOAD_DIR)) {
    return res.status(400).json({ error: 'Invalid path' });
  }

  const jobId = crypto.randomUUID();
  const profileConfig = registry.get(profile || 'default');

  const options = {
    ...profileConfig,
    outputFormat: format,
    watermark: watermark,
    quality: quality || profileConfig.quality,
    maxWidth: maxWidth || profileConfig.maxWidth,
    maxHeight: maxHeight || profileConfig.maxHeight
  };

  shutdownMgr.registerJob(jobId, { originalName: sanitized });

  try {
    const result = await processImage(jobId, inputPath, options);
    await shutdownMgr.completeJob(jobId, 'success');
    res.json({ jobId, output: path.basename(result) });
  } catch (err) {
    await shutdownMgr.completeJob(jobId, 'failed');
    res.status(500).json({ error: 'Processing failed' });
  }
});

// POST /profiles - register custom profile
app.post('/profiles', express.json(), (req, res) => {
  const { name, config } = req.body;
  if (!name || !config) {
    return res.status(400).json({ error: 'name and config required' });
  }
  registry.register(name, config);
  res.json({ status: 'registered' });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  shuttingDown = true;
  if (activeJobs.size === 0) {
    process.exit(0);
  }
  shutdownMgr.onDrain(() => process.exit(0));
  setTimeout(() => process.exit(1), 30000);
});

const server = app.listen(3000, () => {
  console.log('Image processing service running on port 3000');
});

module.exports = { app, registry, shutdownMgr };
